<?php
$title='Edit Product';require 'includes/header.php';$id=(int)$_GET['id'];$st=$pdo->prepare("SELECT * FROM products WHERE id=?");$st->execute([$id]);$p=$st->fetch();$cats=$pdo->query("SELECT * FROM categories ORDER BY name")->fetchAll();if(!$p)die('Product not found');
if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare("UPDATE products SET category_id=?,product_name=?,short_description=?,description=?,price=?,discount_price=?,image=?,warranty=?,featured=? WHERE id=?")->execute([(int)$_POST['category_id'],trim($_POST['product_name']),trim($_POST['short_description']),trim($_POST['description']),$_POST['price']?:null,$_POST['discount_price']?:null,trim($_POST['image']),trim($_POST['warranty']),isset($_POST['featured'])?1:0,$id]);header('Location: products.php');exit;}
?><h1>Edit Product</h1><form method="post" class="card border-0 shadow-sm p-4 mt-3"><div class="row g-3"><div class="col-md-6"><label>Product Name</label><input required name="product_name" value="<?=e($p['product_name'])?>" class="form-control"></div><div class="col-md-6"><label>Category</label><select name="category_id" class="form-select"><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$p['category_id']==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-12"><label>Short Description</label><input name="short_description" value="<?=e($p['short_description'])?>" class="form-control"></div><div class="col-12"><label>Description</label><textarea name="description" rows="5" class="form-control"><?=e($p['description'])?></textarea></div><div class="col-md-4"><label>Price</label><input name="price" value="<?=e($p['price'])?>" type="number" step=".01" class="form-control"></div><div class="col-md-4"><label>Discount Price</label><input name="discount_price" value="<?=e($p['discount_price'])?>" type="number" step=".01" class="form-control"></div><div class="col-md-4"><label>Image URL</label><input name="image" value="<?=e($p['image'])?>" class="form-control"></div><div class="col-md-6"><label>Warranty</label><input name="warranty" value="<?=e($p['warranty'])?>" class="form-control"></div><div class="col-12"><label><input type="checkbox" name="featured" <?=$p['featured']?'checked':''?>> Featured product</label></div><div><button class="btn btn-primary">Update Product</button></div></div></form><?php require 'includes/footer.php';?>